const validatedInput = $('Validate Job Input').first().json || {};

const resumeInput = validatedInput.resume || '';
const mode = validatedInput.mode || 'url';
const rawJobUrl = validatedInput.jobUrl || '';
const jobDescription = validatedInput.jobDescription || '';

const jobUrl =
  mode === 'paste'
    ? 'Paste Mode'
    : rawJobUrl || 'Not provided';

const jobExtraction =
  $('Chain 1 - Job Content Extractor').first().json.text || '';

const gapAnalysis =
  $('Chain 2 - Gap Analyzer').first().json.text || '';

const actionPlan =
  $('Chain 3 - Action Plan Generator').first().json.text || '';

const jobTitle =
  jobExtraction.match(/JOB TITLE:\s*(.+)/i)?.[1]?.trim() ||
  validatedInput.fallbackJobTitle ||
  'Unknown Role';

const company =
  jobExtraction.match(/COMPANY NAME:\s*(.+)/i)?.[1]?.trim() ||
  validatedInput.fallbackCompany ||
  'Unknown Company';

const matchScore = parseInt(
  gapAnalysis.match(/MATCH SCORE:\s*(\d+)/i)?.[1] || '0',
  10
);

const fullReport =
  `CAREER COACH NAVIGATOR REPORT\n\n` +
  `Role: ${jobTitle} at ${company}\n` +
  `Match Score: ${matchScore}%\n` +
  `Mode: ${mode === 'paste' ? 'Paste Mode' : 'URL Mode'}\n` +
  `Generated: ${new Date().toLocaleString()}\n\n` +
  `GAP ANALYSIS\n\n${gapAnalysis}\n\n` +
  `ACTION PLAN\n\n${actionPlan}`;

return [
  {
    json: {
      success: true,
      metadata: {
        generatedAt: new Date().toISOString(),
        jobTitle,
        company,
        jobUrl,
        matchScore: `${matchScore}%`,
        mode
      },
      resumeInput,
      jobDescription,
      gapAnalysis,
      actionPlan,
      fullReport
    }
  }
];

const data = $json || {};

const resume = String(data.resume || '').trim();
const jobUrl = String(data.jobUrl || '').trim();
const jobDescription = String(data.jobDescription || '').trim();
const mode = data.mode || (jobDescription ? 'paste' : 'url');

const rawInputContent = String(data.inputContent || '').trim();

const cleanedInput = rawInputContent
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();

const makeErrorPayload = (errorType, message) => ({
  success: false,
  error: true,
  errorType,
  message,
  metadata: {
    generatedAt: new Date().toISOString(),
    jobTitle: 'Unknown Role',
    company: 'Unknown Company',
    jobUrl: mode === 'paste' ? 'Paste Mode' : (jobUrl || 'Not provided'),
    matchScore: '0%',
    mode
  },
  resumeInput: resume,
  jobDescription,
  gapAnalysis: '',
  actionPlan: '',
  fullReport: message
});

if (!resume || resume.length < 30) {
  return [{ json: makeErrorPayload(
    'MISSING_RESUME',
    'Please provide a valid resume before running the analysis.'
  ) }];
}

if (!cleanedInput || cleanedInput === 'NO CONTENT PROVIDED' || cleanedInput.length < 50) {
  return [{ json: makeErrorPayload(
    'MISSING_JOB_DESCRIPTION',
    mode === 'paste'
      ? 'Please paste a complete job description.'
      : 'The job page could not be read. Please paste the job description manually.'
  ) }];
}

const findMatch = (patterns, fallback) => {
  for (const pattern of patterns) {
    const match = cleanedInput.match(pattern);
    if (match?.[1]) {
      return match[1].replace(/[:|,\-]+$/g, '').trim().slice(0, 100);
    }
  }
  return fallback;
};

const fallbackJobTitle = findMatch(
  [
    /job title[:\s]+(.+?)(?:company|location|department|about|responsibilities|requirements|$)/i,
    /role[:\s]+(.+?)(?:company|location|department|about|responsibilities|requirements|$)/i,
    /position[:\s]+(.+?)(?:company|location|department|about|responsibilities|requirements|$)/i,
    /we are hiring (?:a|an)?\s*(.+?)(?:\.|,| at | for | to )/i
  ],
  'Unknown Role'
);

const fallbackCompany = findMatch(
  [
    /company[:\s]+(.+?)(?:role|job title|location|department|about|responsibilities|requirements|$)/i,
    /about\s+([A-Z][A-Za-z0-9&.\- ]{2,50})[:\s]/i,
    /at\s+([A-Z][A-Za-z0-9&.\- ]{2,50})(?:\.|,|\s)/i
  ],
  'Unknown Company'
);

return [
  {
    json: {
      ...data,
      success: true,
      error: false,
      resume,
      jobUrl,
      jobDescription,
      mode,
      inputContent: cleanedInput,
      fallbackJobTitle,
      fallbackCompany,
      inputLength: cleanedInput.length
    }
  }
];
